1: //! 会话标题自动生成（first-prompt LLM，04 §4 `[session_title]`）。
2: //!
3: //! 语义对齐上游 `dsh-session-title-first-prompt-llm`（base bundle 的开箱默认）：
4: //! **全新会话**（无父——分叉永不自动生成）收到首条用户消息后，用生效路由发一次
5: //! 辅助请求总结该消息生成标题，写进 `titles.json` 侧车；截断派生（rollout::summarize）
6: //! 降级为 fallback——生成失败、超时、输入超限都保持 fallback，不自动重试；生成期间
7: //! 用户手改（`set_title`）优先，生成结果不覆盖。
8: //!
9: //! 辅助请求**不进入会话历史**、不加主回合的 token 与延迟（fire-and-forget）；
10: //! 日志只记结果不记内容（首条消息是用户内容，标题请求与主请求同一条脱敏纪律）。
11: 
12: use std::path::Path;
13: 
14: use futures::StreamExt;
15: use tauri::Manager;
16: 
17: use crate::config::SessionTitleConfig;
18: use crate::model_client::{self, HistoryItem, ModelStreamEvent, provider::ProviderConfig, Role};
19: 
20: // ============================== 纯函数（提示 / 框架 / 解析） ==============================
21: 
22: /// 辅助请求的系统指令（对齐上游 first-prompt-llm 的 `systemPrompt`）。
23: pub fn system_prompt(config: &SessionTitleConfig) -> String {
24:     [
25:         "Create a concise title for an AI coding-assistant session from the supplied human messages.",
26:         "Return only the title on one line, **in plain text of natural language**, with no quotes, prefix, explanation, Markdown, XML, or terminal control codes. No code is allowed.",
27:         "Use the language of the messages.",
28:         format!(
29:             "Aim for about {} words in non-CJK languages or {} CJK characters.",
30:             config.target_words, config.target_cjk_characters
31:         )
32:         .as_str(),
33:         "If the messages give little to name, still return a short best-effort title, such as Greeting, instead of explaining.",
34:     ]
35:     .join("\n")
36: }
37: 
38: /// 清洗控制字符并归一空白（对齐上游 `cleanTitleText`）：去 OSC / CSI / 其余 ESC
39: /// 序列、C0/C1 控制字符、双向文本控制符，空白折叠成单空格。标题是界面元数据，
40: /// 终端转义序列混进来会直接污染侧栏渲染。
41: pub fn normalize_title_text(input: &str) -> String {
42:     let mut out = String::with_capacity(input.len());
43:     let mut chars = input.chars().peekable();
44:     while let Some(c) = chars.next() {
45:         match c {
46:             '\x1b' => match chars.peek() {
47:                 // CSI：ESC [ … 直到 0x40–0x7E 区间的终止字节
48:                 Some('[') => {
49:                     chars.next();
50:                     while let Some(&n) = chars.peek() {
51:                         chars.next();
52:                         if ('\x40'..='\x7e').contains(&n) {
53:                             break;
54:                         }
55:                     }
56:                 }
57:                 // OSC：ESC ] … 直到 BEL 或 ST（ESC \）
58:                 Some(']') => {
59:                     chars.next();
60:                     while let Some(&n) = chars.peek() {
61:                         chars.next();
62:                         if n == '\x07' {
63:                             break;
64:                         }
65:                         if n == '\x1b' {
66:                             chars.next();
67:                             break;
68:                         }
69:                     }
70:                 }
71:                 // 其余两字符转义序列：吞掉随后的一个字符
72:                 _ => {
73:                     chars.next();
74:                 }
75:             },
76:             c if c.is_control() && !c.is_whitespace() => {}
77:             '\u{202a}'..='\u{202e}' | '\u{2066}'..='\u{2069}' => {}
78:             c => out.push(c),
79:         }
80:     }
81:     out.split_whitespace().collect::<Vec<_>>().join(" ")
82: }
83: 
84: /// 整行被同一对 `*`/`**` 包裹时剥掉标记：模型无视"单行无 Markdown"指令时的常见
85: /// 形态；内部还含标记的行不动（那可能是字面星号）。
86: fn strip_whole_line_emphasis(line: &str) -> String {
87:     for marker in ["**", "*"] {
88:         if let Some(inner) = line.strip_prefix(marker) {
89:             if let Some(stripped) = inner.strip_suffix(marker) {
90:                 if !stripped.is_empty() && !stripped.contains(marker) {
91:                     return stripped.to_string();
92:                 }
93:             }
94:         }
95:     }
96:     line.to_string()
97: }
98: 
99: /// 从模型输出取标题：首个非空行（模型把注释写在标题后面时只取标题），归一化后
100: /// 为空即拒绝——空标题会让侧栏行看起来"会话没有内容"。
101: pub fn title_from_reply(text: &str) -> Result<String, String> {
102:     let line = text
103:         .split(['\r', '\n'])
104:         .map(str::trim)
105:         .find(|line| !line.is_empty())
106:         .unwrap_or("");
107:     let title = normalize_title_text(&strip_whole_line_emphasis(line));
108:     if title.is_empty() {
109:         return Err("模型输出没有可用的标题行".into());
110:     }
111:     Ok(title)
112: }
113: 
114: /// 消息 JSON 框架：用户文本作为 JSON 字符串值进结构——文本里出现任何引号、
115: /// 大括号、换行都拆不掉框架（对齐上游 `frameMessages` 的防注入姿态）。
116: pub fn frame_messages(text: &str) -> String {
117:     serde_json::json!({ "messages": [{ "text": text }] }).to_string()
118: }
119: 
120: /// 资格判定（first-prompt 节奏）：无父（分叉永不自动生成，即使分叉源是空会话）
121: /// 且历史里还没有任何用户消息（续跑、崩溃恢复都不重新生成）。
122: pub fn eligible(parent_id: Option<&str>, history: &[HistoryItem]) -> bool {
123:     parent_id.is_none()
124:         && !history
125:             .iter()
126:             .any(|item| matches!(item, HistoryItem::Message { role: Role::User, .. }))
127: }
128: 
129: /// 生成期间用户改了名（`titles.json` 已有该会话条目）就不覆盖——用户手改优先。
130: pub fn user_took_over(dir: &Path, agent_id: &str) -> bool {
131:     crate::rollout::read_titles(dir).contains_key(agent_id)
132: }
133: 
134: // ============================== 辅助请求 ==============================
135: 
136: fn title_history(first_message: &str) -> Vec<HistoryItem> {
137:     vec![HistoryItem::Message {
138:         role: Role::User,
139:         text: first_message.to_string(),
140:         reasoning: None,
141:     }]
142: }
143: 
144: /// 执行一次标题生成：框架后的输入超限**拒绝**（截断会让标题基于被切开的文本编造），
145: /// 流式消费到收口，端到端超时掐断（迟到的成功不采纳）。返回的标题已过
146: /// [`title_from_output`] 归一化，非空。
147: async fn generate_title(
148:     provider: &ProviderConfig,
149:     api_key: &str,
150:     first_message: &str,
151:     config: &SessionTitleConfig,
152: ) -> Result<String, String> {
153:     let input = frame_messages(first_message);
154:     if input.len() as u64 > config.max_input_bytes {
155:         return Err(format!(
156:             "标题输入 {} 字节超过上限 {}（不截断，保持 fallback）",
157:             input.len(),
158:             config.max_input_bytes
159:         ));
160:     }
161:     let system = system_prompt(config);
162:     let history = title_history(first_message);
163:     let mut body = if provider.is_responses() {
164:         model_client::build_responses_request(provider, &history, &[], &system)
165:     } else {
166:         model_client::build_chat_request(provider, &history, &[], &system)
167:     };
168:     // 输出上限是防失控的兜底；两个协议族的字段名不同，注入进各自的请求体
169:     if provider.is_responses() {
170:         body["max_output_tokens"] = serde_json::json!(config.max_output_tokens);
171:     } else {
172:         body["max_tokens"] = serde_json::json!(config.max_output_tokens);
173:     }
174:     let mut stream = model_client::stream_body(provider, api_key, body)
175:         .await
176:         .map_err(|error| error.human)?;
177:     let mut text = String::new();
178:     let consumed = tokio::time::timeout(
179:         std::time::Duration::from_millis(config.timeout_ms),
180:         async {
181:             while let Some(event) = stream.next().await {
182:                 match event {
183:                     ModelStreamEvent::OutputTextDelta { delta } => text.push_str(&delta),
184:                     ModelStreamEvent::Failed { message, .. } => {
185:                         return Err(format!("标题流失败: {message}"))
186:                     }
187:                     ModelStreamEvent::Completed { .. } => break,
188:                     _ => {} // 思考增量与结构化项不进标题
189:                 }
190:             }
191:             Ok::<(), String>(())
192:         },
193:     )
194:     .await;
195:     match consumed {
196:         Err(_) => Err(format!("标题生成超过 {}ms 超时（保持 fallback）", config.timeout_ms)),
197:         Ok(Err(e)) => Err(e),
198:         Ok(Ok(())) => title_from_output(&text),
199:     }
200: }
201: 
202: /// 入口：前置不满足就静默返回（关开关、没密钥都不是错误——fallback 派生标题一直
203: /// 在）；满足则派生后台任务，成功写侧车、失败留日志。绝不阻塞主回合。
204: pub fn spawn_generation(app: tauri::AppHandle, agent_id: String, first_message: String) {
205:     let state = app.state::<crate::app_state::AppState>();
206:     let cfg = state.config();
207:     if !cfg.session_title.enabled {
208:         return;
209:     }
210:     let active = cfg.effective_model();
211:     // 标题辅助请求不启用推理档：档位属于主回合的采样质量选择，辅助请求要的是
212:     // 快与省，带上档位只会拖慢标题生成并多烧 token。自定义请求头照带（部署头
213:     // 是端点级的，比如企业代理签名——少一个头就可能打不进去）。
214:     let provider = ProviderConfig {
215:         provider: active.provider.clone(),
216:         base_url: active.base_url.clone(),
217:         model: active.model.clone(),
218:         reasoning_effort: None,
219:         headers: active.headers.clone(),
220:     };
221:     let api_key = match crate::config::SecretStore::new(&state.config_root()).load_key(&active.secret_name) {
222:         Ok(Some(key)) => key,
223:         _ => return,
224:     };
225:     let title_config = cfg.session_title.clone();
226:     let dir = state.data_root().join(crate::rollout::ROLLOUT_DIR);
227:     tauri::async_runtime::spawn(async move {
228:         match generate_title(&provider, &api_key, &first_message, &title_config).await {
229:             Ok(title) => {
230:                 if user_took_over(&dir, &agent_id) {
231:                     return;
232:                 }
233:                 if let Err(e) = crate::rollout::set_title(&dir, &agent_id, &title) {
234:                     tracing::warn!("标题写入失败（fallback 保持）: {e:?}");
235:                 }
236:             }
237:             Err(e) => tracing::debug!("标题生成未完成，保持派生标题: {e}"),
238:         }
239:     });
240: }
